// ipow_rig.v -- k2/collatz_rig.v (= cells/hw/gcd_rig.v's closed ring) with bdc_ipow (probe K3,
// generated by formal/tools-A/xaudit/k3/gen_rig.py; do not edit by hand).
//   * DUT bdc_ipow (b, e, start) -> (out0, end); the fork has N = 3;
//   * ROM {expected, b, e} from kernels/ipow/ipow.c semantics (gen_rig.py), not from a run;
//   * everything else (uenv0/uenv1, urdly(CMPD), p_end sink, err/ok filter) as collatz_rig.v.
// Not part of cells/: built only in an exported copy of the tree (k3/build_k3.sh).
`default_nettype none
module ipow_rig #(parameter integer IDXW  = 4,
                 parameter integer WFILT = 2,
                 parameter integer CMPD  = 16)
    (input  wire            rst,
     input  wire [IDXW-1:0] idx,
     output wire            lap,
     output wire            err_flt,
     output wire            ok_flt,
     output wire            probe,
     output wire [31:0]     res_data);

    function [95:0] vector(input [3:0] i);
        case (i)
            4'd0: vector = {32'h0000088b, 32'h00000003, 32'h00000007};
            4'd1: vector = {32'h00000009, 32'h00000003, 32'h00000002};
            4'd2: vector = {32'h00000400, 32'h00000002, 32'h0000000a};
            4'd3: vector = {32'h0000007d, 32'h00000005, 32'h00000003};
            4'd4: vector = {32'h00000001, 32'h00000007, 32'h00000000};
            4'd5: vector = {32'hffffffe0, 32'hfffffffe, 32'h00000005};
            4'd6: vector = {32'h3b9aca00, 32'h0000000a, 32'h00000009};
            4'd7: vector = {32'hcfd41b91, 32'h00000003, 32'h00000014};
            4'd8: vector = {32'h80000000, 32'h00000002, 32'h0000001f};
            4'd9: vector = {32'h00000001, 32'h00000001, 32'h000003e8};
            4'd10: vector = {32'h00000000, 32'h00000000, 32'h00000005};
            4'd11: vector = {32'h00006f91, 32'h0000000d, 32'h00000004};
            4'd12: vector = {32'h0000b640, 32'h00000006, 32'h00000006};
            4'd13: vector = {32'h00000009, 32'h00000009, 32'h00000001};
            4'd14: vector = {32'hffffffff, 32'hffffffff, 32'h00000007};
            4'd15: vector = {32'h9fc99c81, 32'h00000011, 32'h00000008};
        endcase
    endfunction
    wire [95:0] vec = vector(idx);
    wire [31:0] b_v = vec[31:0];
    wire [31:0] a_v = vec[63:32];
    wire [31:0] g_v = vec[95:64];

    wire a_req, a_ack, b_req, b_ack, start_req, start_ack;
    wire out0_req, out0_ack, p_end_req, p_end_ack;
    wire [31:0] out0_data;

`ifdef IPOW_DUT_PARAMS
    bdc_ipow #(`IPOW_DUT_PARAMS) udut (
`else
    bdc_ipow udut (
`endif
        .rst(rst),
        .b_req(a_req), .b_ack(a_ack), .b_data(a_v),
        .e_req(b_req), .e_ack(b_ack), .e_data(b_v),
        .start_req(start_req), .start_ack(start_ack),
        .out0_req(out0_req),   .out0_ack(out0_ack),   .out0_data(out0_data),
        .p_end_req(p_end_req), .p_end_ack(p_end_ack));

    wire env_c, in_ack;
    wire [2:0] in_req, in_acks;
    assign in_acks = {start_ack, b_ack, a_ack};
    assign {start_req, b_req, a_req} = in_req;
    bd_fork #(.N(3)) ufork (
        .rst(rst), .req(env_c), .ack(in_ack),
        .req_out(in_req), .ack_in(in_acks));

    bd_delay #(.N(2)) upsnk (.a(p_end_req), .z(p_end_ack));

    wire res_req, res_ack;
    bd_delay #(.N(CMPD)) urdly (.a(out0_req), .z(res_req));
    assign out0_ack = res_ack;

    wire env_c0;
    bd_c2n     uenv0 (.a(res_req), .b(env_c),  .rst(rst), .q(env_c0));
    bd_c2n_set uenv1 (.a(env_c0),  .b(in_ack), .rst(rst), .q(env_c));
    assign res_ack = env_c0;

    wire mism = |(out0_data ^ g_v);
    wire err_raw, ok_raw, err_d, ok_d;
    (* keep *) LUT2 #(.INIT(4'h8)) uerr_d (.I0(mism), .I1(res_req), .O(err_raw));
    (* keep *) LUT2 #(.INIT(4'h4)) uok_d  (.I0(mism), .I1(res_req), .O(ok_raw));
    bd_delay #(.N(WFILT)) uerr_w (.a(err_raw), .z(err_d));
    bd_delay #(.N(WFILT)) uok_w  (.a(ok_raw),  .z(ok_d));
    (* keep *) LUT2 #(.INIT(4'h8)) uerr_a (.I0(err_raw), .I1(err_d), .O(err_flt));
    (* keep *) LUT2 #(.INIT(4'h8)) uok_a  (.I0(ok_raw),  .I1(ok_d),  .O(ok_flt));

    assign lap      = res_req;
    assign probe    = env_c;
    assign res_data = out0_data;
endmodule
`default_nettype wire
